import numpy as np
def basis(kind):
    if kind=='poly2': return [np.ones_like(t),t,t**2]
    if kind=='poly3': return [np.ones_like(t),t,t**2,t**3]
    if kind=='logexp': return [np.ones_like(t),np.log(t),t,t**2]
    if kind=='inv': return [np.ones_like(t),1/t,t,t**2]
    if kind=='expb': return [np.ones_like(t),np.exp(-t),np.exp(0.3*t),t]
def fit(a,b,B):
    X=np.array([-(f*A**a) for f in B]+[(f*A**b) for f in B]).T
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    return np.mean((X@c-dA_dt)**2)/np.var(dA_dt)
for kind in ['poly2','poly3','logexp','inv','expb']:
    B=basis(kind)
    res=[]
    for a in np.arange(0,1.51,0.125):
        for b in np.arange(0.5,4.01,0.125):
            if abs(a-b)<0.05: continue
            res.append((fit(a,b,B),a,b))
    res.sort()
    print(kind,[ (round(x[0],6),x[1],x[2]) for x in res[:3]])

